vol_cuboid = lambda l, b, h: l * b * h
import math
vol_cylinder = lambda r, h: round(math.pi * r * r * h, 2)

def poly_vol(*args):
    if len(args) == 1:
        return args[0] ** 3
    elif len(args) == 3:
        return args[0] * args[1] * args[2]

shape = input().strip()
dims = list(map(int, input().split()))

if shape == 'cube':
    print(poly_vol(dims[0]))
elif shape == 'cuboid':
    print(poly_vol(*dims))
elif shape == 'cylinder':
    print(vol_cylinder(dims[0], dims[1]))
